package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Identificado;
import java.math.BigDecimal;

/**
 * Forma de entrega. Cada parceria nova é uma implementação nova, com seu jeito
 * de cobrar, seu prazo e suas limitações.
 */
public interface ModalidadeEntrega extends Identificado {

    /** Frete em reais para o peso do pedido, já em centavos. */
    BigDecimal frete(BigDecimal pesoKg);

    int prazoDias();

    /** Se a modalidade atende um pedido com esse peso. */
    default boolean atende(BigDecimal pesoKg) {
        return true;
    }
}
EOF
cat > EntregaPorPeso.java <<'EOF'
package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Dinheiro;
import java.math.BigDecimal;

/** Base das modalidades que cobram uma parte fixa mais um valor por kg. */
abstract class EntregaPorPeso implements ModalidadeEntrega {

    private final BigDecimal fixo;
    private final BigDecimal porKg;

    EntregaPorPeso(String fixo, String porKg) {
        this.fixo = new BigDecimal(fixo);
        this.porKg = new BigDecimal(porKg);
    }

    @Override
    public BigDecimal frete(BigDecimal pesoKg) {
        return Dinheiro.centavos(fixo.add(porKg.multiply(pesoKg)));
    }
}
EOF
