2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.ContextoCupom;
5	import com.loja.checkout.cupom.Cupom;
6	import com.loja.checkout.cupom.SemCupom;
7	import com.loja.checkout.dominio.Catalogo;
8	import com.loja.checkout.dominio.CodigoErro;
9	import com.loja.checkout.dominio.Dinheiro;
10	import com.loja.checkout.dominio.Item;
11	import com.loja.checkout.dominio.PedidoRecusadoException;
12	import com.loja.checkout.dominio.Regiao;
13	import com.loja.checkout.entrega.ModalidadeEntrega;
14	import com.loja.checkout.pagamento.FormaPagamento;
15	import com.loja.checkout.pagamento.ResultadoPagamento;
16	import com.loja.checkout.web.ItemRequest;
17	import com.loja.checkout.web.ResumoRequest;
18	import com.loja.checkout.web.ResumoResponse;
19	import java.math.BigDecimal;
20	import java.util.ArrayList;
21	import java.util.List;
22	import org.springframework.stereotype.Service;
23	
24	/**
25	 * Orquestra a ordem do cálculo e as conferências. As regras de cada caso moram
26	 * nas implementações de modalidade, cupom, nível de clube e forma de pagamento.
27	 */
28	@Service
29	public class CalculadoraDeResumo {
30	
31	    private static final Cupom SEM_CUPOM = new SemCupom();
32	
33	    private final Catalogo<ModalidadeEntrega> entregas;
34	    private final Catalogo<Cupom> cupons;
35	    private final Catalogo<NivelClube> niveisClube;
36	    private final Catalogo<FormaPagamento> formasPagamento;
37	
38	    public CalculadoraDeResumo(Catalogo<ModalidadeEntrega> entregas, Catalogo<Cupom> cupons,
39	            Catalogo<NivelClube> niveisClube, Catalogo<FormaPagamento> formasPagamento) {
40	        this.entregas = entregas;
41	        this.cupons = cupons;
42	        this.niveisClube = niveisClube;
43	        this.formasPagamento = formasPagamento;
44	    }
45	
46	    public ResumoResponse calcular(ResumoRequest pedido) {
47	        List<Item> itens = conferirItens(pedido.itens());
48	        NivelClube clube = niveisClube.obrigatorio(pedido.nivelClube());
49	        Regiao regiao = Regiao.doCodigo(pedido.regiao());
50	
51	        BigDecimal peso = pesoTotal(itens);
52	        ModalidadeEntrega entrega = entregas.obrigatorio(pedido.modalidadeEntrega());
53	        if (!entrega.atende(peso)) {
54	            throw new PedidoRecusadoException(CodigoErro.MODALIDADE_INDISPONIVEL);
55	        }
56	
57	        BigDecimal subtotal = subtotalProdutos(itens);
58	        BigDecimal frete = clube.isentaFrete() ? Dinheiro.ZERO : entrega.frete(peso);
59	
60	        Cupom cupom = cupom(pedido.cupom());
61	        ContextoCupom contexto = new ContextoCupom(itens, subtotal, frete);
62	        if (!cupom.aplicavel(contexto)) {
63	            throw new PedidoRecusadoException(CodigoErro.CUPOM_NAO_APLICAVEL);
64	        }
65	        BigDecimal desconto = cupom.desconto(contexto);
66	
67	        BigDecimal seguro = regiao.seguroSobre(subtotal);
68	        BigDecimal totalPedido =
69	                Dinheiro.centavos(subtotal.subtract(desconto).add(frete).add(seguro));
70	
71	        FormaPagamento pagamento = formasPagamento.obrigatorio(pedido.formaPagamento());
72	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
73	        if (!pagamento.aceitaParcelas(parcelas)) {
74	            throw new PedidoRecusadoException(CodigoErro.PARCELAMENTO_INVALIDO);
75	        }
76	        if (!pagamento.atende(totalPedido)) {
77	            throw new PedidoRecusadoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
78	        }
79	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
80	
81	        return new ResumoResponse(
82	                subtotal,
83	                desconto,
84	                frete,
85	                entrega.prazoDias(),
86	                seguro,
87	                Dinheiro.centavos(resultado.totalFinal().subtract(totalPedido)),
88	                resultado.totalFinal(),
89	                parcelas,
90	                resultado.valorParcela(),
91	                clube.credito(subtotal),
92	                clube.temBrinde(subtotal));
93	    }
94	
95	    private List<Item> conferirItens(List<ItemRequest> itens) {
96	        if (itens == null || itens.isEmpty()) {
97	            throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
98	        }
99	        List<Item> conferidos = new ArrayList<>();
100	        for (ItemRequest item : itens) {
101	            if (item == null || naoEPositivo(item.precoUnitario()) || naoEPositivo(item.pesoKg())
102	                    || item.quantidade() == null || item.quantidade() <= 0) {
103	                throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
104	            }
105	            conferidos.add(new Item(item.nome(), item.precoUnitario(), item.quantidade(),
106	                    item.pesoKg()));
107	        }
108	        return conferidos;
109	    }
110	
111	    private boolean naoEPositivo(BigDecimal valor) {
112	        return valor == null || valor.compareTo(BigDecimal.ZERO) <= 0;
113	    }
114	
115	    private Cupom cupom(String codigo) {
116	        if (codigo == null || codigo.isBlank()) {
117	            return SEM_CUPOM;
118	        }
119	        return cupons.obrigatorio(codigo);
120	    }
121	
122	    private BigDecimal subtotalProdutos(List<Item> itens) {
123	        BigDecimal subtotal = BigDecimal.ZERO;
124	        for (Item item : itens) {
125	            subtotal = subtotal.add(item.total());
126	        }
127	        return Dinheiro.centavos(subtotal);
128	    }
129	
130	    private BigDecimal pesoTotal(List<Item> itens) {
131	        BigDecimal peso = BigDecimal.ZERO;
132	        for (Item item : itens) {
133	            peso = peso.add(item.peso());
134	        }
135	        return peso;
136	    }
137	}
