6	/** Arredondamento de dinheiro: centavos, meio para o par. */
7	public final class Dinheiro {
8	
9	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
10	
11	    private Dinheiro() {
12	    }
13	
14	    public static BigDecimal centavos(BigDecimal valor) {
15	        return valor.setScale(2, RoundingMode.HALF_EVEN);
16	    }
17	
