2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import org.springframework.stereotype.Component;
7	
8	/** Até 3x sem juros; de 4x a 12x com juros de 1,99% ao mês (tabela Price). */
9	@Component
10	class PagamentoCartao implements FormaPagamento {
11	
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final int MAXIMO_PARCELAS_SEM_JUROS = 3;
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	    private static final MathContext PRECISAO = MathContext.DECIMAL64;
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean aceitaParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
25	    }
26	
27	    @Override
28	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
29	        if (parcelas <= MAXIMO_PARCELAS_SEM_JUROS) {
30	            return new ResultadoPagamento(Dinheiro.centavos(totalPedido),
31	                    Dinheiro.dividir(totalPedido, parcelas));
32	        }
33	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
34	        return new ResultadoPagamento(
35	                Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
36	    }
37	
38	    /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas) */
39	    private BigDecimal parcelaPrice(BigDecimal totalPedido, int parcelas) {
40	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
41	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, PRECISAO));
42	        return totalPedido.multiply(TAXA_MENSAL).divide(divisor, PRECISAO);
43	    }
44	}
