1	package com.loja.checkout.dominio;
2	
3	import java.util.Collection;
4	import java.util.LinkedHashMap;
5	import java.util.Map;
6	
7	/**
8	 * Escolhe o caso pelo código, por consulta num mapa: entrar um caso novo é
9	 * entrar uma classe nova, sem mexer em quem escolhe.
10	 */
11	public class Catalogo<T extends Identificado> {
12	
13	    private final Map<String, T> porCodigo = new LinkedHashMap<>();
14	    private final CodigoErro erroQuandoNaoExiste;
15	
16	    public Catalogo(Collection<T> casos, CodigoErro erroQuandoNaoExiste) {
17	        this.erroQuandoNaoExiste = erroQuandoNaoExiste;
18	        casos.forEach(caso -> porCodigo.put(caso.codigo(), caso));
19	    }
20	
21	    public T obrigatorio(String codigo) {
22	        T caso = codigo == null ? null : porCodigo.get(codigo);
23	        if (caso == null) {
24	            throw new PedidoRecusadoException(erroQuandoNaoExiste);
25	        }
26	        return caso;
27	    }
28	}
